Пример 1: Подсчет количества четных элементов в массиве
```pascal
var
    a: array[1..10] of integer;
    i, count: integer;
begin
    { Заполнение массива }
    randomize;
    for i := 1 to 10 do
        a[i] := random(100);

    { Вывод массива }
    write('Массив: ');
    for i := 1 to 10 do
        write(a[i], ' ');

    { Подсчет четных элементов }
    count := 0;
    for i := 1 to 10 do
        if a[i] mod 2 = 0 then
            count := count + 1;

    { Вывод результата }
    writeln('Количество четных элементов: ', count);
end.
```

Пример 2: Сумма элементов на четных позициях
```pascal
var
    a: array[1..5] of integer;
    i, sum: integer;
begin
    { Ввод массива }
    writeln('Введите 5 чисел:');
    for i := 1 to 5 do
        read(a[i]);

    { Вычисление суммы на четных позициях }
    sum := 0;
    for i := 2 to 5 do
        if i mod 2 = 0 then
            sum := sum + a[i];

    { Вывод результата }
    writeln('Сумма элементов на четных позициях: ', sum);
end.
```

Пример 3: Замена отрицательных элементов на их модули
```pascal
var
    a: array[1..15] of integer;
    i: integer;
begin
    { Заполнение массива }
    randomize;
    for i := 1 to 15 do
        a[i] := random(100) - 50;  { числа от -50 до 49 }

    { Вывод исходного массива }
    write('Исходный массив: ');
    for i := 1 to 15 do
        write(a[i], ' ');

    { Замена отрицательных элементов }
    for i := 1 to 15 do
        if a[i] < 0 then
            a[i] := -a[i];

    { Вывод измененного массива }
    writeln('Измененный массив: ');
    for i := 1 to 15 do
        write(a[i], ' ');
end.
```

Пример 4: Сортировка массива по возрастанию (пузырьковая сортировка)
```pascal
var
    a: array[1..20] of integer;
    i, j, temp: integer;
begin
    { Заполнение массива }
    randomize;
    for i := 1 to 20 do
        a[i] := random(100);

    { Вывод исходного массива }
    write('Исходный массив: ');
    for i := 1 to 20 do
        write(a[i], ' ');

    { Сортировка }
    for i := 1 to 19 do
        for j := i+1 to 20 do
            if a[i] > a[j] then
            begin
                temp := a[i];
                a[i] := a[j];
                a[j] := temp;
            end;

    { Вывод отсортированного массива }
    writeln('Отсортированный массив: ');
    for i := 1 to 20 do
        write(a[i], ' ');
end.
```

